package com.andye.warmod.block.entity;import com.andye.warmod.block.RadarStationBlock;import com.andye.warmod.block.RadarStationStructure;import com.andye.warmod.radar.station.*;import java.util.*;import net.minecraft.SharedConstants;import net.minecraft.core.*;import net.minecraft.core.UUIDUtil;import net.minecraft.network.protocol.Packet;import net.minecraft.network.protocol.game.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.phys.Vec3;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.storage.*;import org.jspecify.annotations.Nullable;public final class RadarStationBlockEntity extends BlockEntity {private UUID radarId=UUID.randomUUID();private Direction facing=Direction.NORTH;private @Nullable UUID ownerId;private String ownerName="SERVER";private double warningRadius=RadarStationConstants.DEFAULT_WARNING_RADIUS;private long phaseOffset;private boolean warningActive,teardown;private final Map<UUID,RadarStationObservation>observations=new LinkedHashMap<>();public RadarStationBlockEntity(BlockPos p,BlockState s){super(ModBlockEntities.RADAR_STATION,p,s);if(s.hasProperty(RadarStationBlock.FACING))facing=s.getValue(RadarStationBlock.FACING);}public void initialize(ServerLevel level,Direction facing,@Nullable Player owner){radarId=UUID.randomUUID();this.facing=facing;ownerId=owner==null?null:owner.getUUID();ownerName=owner==null?"SERVER":owner.getGameProfile().name();phaseOffset=RadarSweepMath.phaseOffset(radarId);sync();}public UUID radarId(){return radarId;}public Direction facing(){return facing;}public @Nullable UUID ownerId(){return ownerId;}public String ownerName(){return ownerName;}public double warningRadius(){return warningRadius;}public long phaseOffset(){return phaseOffset;}public boolean warningActive(){return warningActive;}public int threatCount(){return(int)observations.values().stream().filter(RadarStationObservation::threatensWarningZone).count();}public Collection<RadarStationObservation>observations(){return List.copyOf(observations.values());}public void setTeardownInProgress(boolean v){teardown=v;}public boolean teardownInProgress(){return teardown;}public void setWarningRadius(double value){double clamped=Math.max(RadarStationConstants.MIN_WARNING_RADIUS,Math.min(RadarStationConstants.MAX_WARNING_RADIUS,value));warningRadius=Math.round(clamped/RadarStationConstants.WARNING_INCREMENT)*(double)RadarStationConstants.WARNING_INCREMENT;if(level instanceof ServerLevel server){Vec3 c=Vec3.atCenterOf(worldPosition);observations.replaceAll((id,o)->{double dx=o.predictedImpactPosition().x-c.x,dz=o.predictedImpactPosition().z-c.z;return new RadarStationObservation(o.trackId(),o.payloadType(),o.phase(),o.observedPosition(),o.observedVelocity(),o.predictedImpactPosition(),o.observationGameTime(),dx*dx+dz*dz<=warningRadius*warningRadius);});updateWarning(server);}RadarStationManager.updateRecord(this);sync();}public boolean observe(ServerLevel level,RadarStationObservation o){observations.put(o.trackId(),o);while(observations.size()>RadarStationConstants.MAX_OBSERVATIONS)observations.remove(observations.keySet().iterator().next());return updateWarning(level);}public boolean prune(ServerLevel level,long now,Set<UUID>active){observations.values().removeIf(o->!active.contains(o.trackId())||now-o.observationGameTime()>RadarStationConstants.SWEEP_PERIOD_TICKS*2L);return updateWarning(level);}private boolean updateWarning(ServerLevel level){boolean next=observations.values().stream().anyMatch(RadarStationObservation::threatensWarningZone);if(next==warningActive)return false;warningActive=next;for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)level.updateNeighborsAt(worldPosition.offset(x,0,z),getBlockState().getBlock());sync();if(SharedConstants.IS_RUNNING_IN_IDE)com.andye.warmod.WarMod.LOGGER.info("Radar station {} warning state changed: active={}, threats={}",radarId,warningActive,threatCount());return true;}public void sync(){setChanged();if(level!=null)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);}@Override protected void saveAdditional(ValueOutput o){super.saveAdditional(o);o.store("radar_id",UUIDUtil.CODEC,radarId);o.putString("facing",facing.getSerializedName());o.storeNullable("owner_id",UUIDUtil.CODEC,ownerId);o.putString("owner_name",ownerName);o.putDouble("warning_radius",warningRadius);o.putLong("phase_offset",phaseOffset);o.putBoolean("warning_active",warningActive);}@Override protected void loadAdditional(ValueInput i){super.loadAdditional(i);radarId=i.read("radar_id",UUIDUtil.CODEC).orElseGet(UUID::randomUUID);facing=Direction.byName(i.getStringOr("facing","north"));if(facing==null||!facing.getAxis().isHorizontal())facing=Direction.NORTH;ownerId=i.read("owner_id",UUIDUtil.CODEC).orElse(null);ownerName=i.getStringOr("owner_name","SERVER");warningRadius=Math.max(RadarStationConstants.MIN_WARNING_RADIUS,Math.min(RadarStationConstants.MAX_WARNING_RADIUS,i.getDoubleOr("warning_radius",RadarStationConstants.DEFAULT_WARNING_RADIUS)));phaseOffset=i.getLongOr("phase_offset",RadarSweepMath.phaseOffset(radarId));warningActive=i.getBooleanOr("warning_active",false);}@Override public @Nullable Packet<ClientGamePacketListener>getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public net.minecraft.nbt.CompoundTag getUpdateTag(net.minecraft.core.HolderLookup.Provider p){return saveCustomOnly(p);}}